def solve(s, t):
    # If lengths differ, they can't be rearrangements
    if len(s) != len(t):
        return False

    # Use a frequency counter with a dictionary
    count = {}

    # Count characters in s
    for char in s:
        count[char] = count.get(char, 0) + 1

    # Subtract counts for characters in t
    for char in t:
        if char not in count:
            return False
        count[char] -= 1
        if count[char] == 0:
            del count[char]

    # If all counts are zero, they are rearrangements
    return not count

