def solve(n, edges):
    # Initialize parent array for union-find
    parent = list(range(n))

    # Find root of a node with path compression
    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    # Union two nodes
    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    # Process each edge
    for u, v in edges:
        union(u, v)

    # Count the number of unique roots (connected components)
    return len({find(i) for i in range(n)})

