    # Initialize parent array for Union-Find
    parent = list(range(n))

    # Find root of a node with path compression
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    # Union two nodes
    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_y] = root_x

    # Process each edge
    for u, v in edges:
        union(u, v)

    # Count unique roots (connected components)
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)

