def solve(n, edges):
    def bfs(start):
        queue = [start]
        visited = set([start])
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return visited

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    components = 0
    for i in range(n):
        if i not in visited:
            component = bfs(i)
            visited.update(component)
            components += 1
    return components

