def solve(n, edges):
    def add_edges(adj, u, v):
        adj[u].append(v)
        adj[v].append(u)

    adj = [[] for _ in range(n)]
    for u, v in edges:
        add_edges(adj, u, v)

    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

    return count
